# Let me verify the rule more carefully
# The output matches component 3 exactly when scaled to 4x4
# Comp 3: size=9, bounds=4x4

# So the rule might be: take the component whose bounding box is the target size
# or take the largest component that also has a certain property

# Let me check all components' scaled versions
values_map = {}
output = demo1_output

r, c, comps_8 = find_components_8connect(demo1_input)

for i, comp in enumerate(comps_8):
    r_coords = sorted([r for r, cc in comp])
    c_coords = sorted([cc for r, cc in comp])
    h = r_coords[-1] - r_coords[0] + 1
    w = c_coords[-1] - c_coords[0] + 1

    # Scale to 4x4
    scaled = [[0]*4 for _ in range(4)]
    for rr, cc in comp:
        scaled_r = int((rr - r_coords[0]) * 4 / h) if h > 0 else 0
        scaled_c = int((cc - c_coords[0]) * 4 / w) if w > 0 else 0
        if scaled_r < 4 and scaled_c < 4:
            scaled[scaled_r][scaled_c] = 1

    # Check if this matches output
    match = True
    for ii in range(4):
        for jj in range(4):
            if scaled[ii][jj] != output[ii][jj]:
                match = False
                break
        if not match:
            break

    if match:
        print(f"Component {i}: MATCHES OUTPUT")
        print(f"  Size={len(comp)}, bounds={h}x{w}")
    else:
        values_map[i] = ("bounds", h, w, len(comp))

# Also let me check if OR-ing all scaled components gives the output
combined = [[0]*4 for _ in range(4)]
for i, comp in enumerate(comps_8):
    r_coords = sorted([r for r, cc in comp])
    c_coords = sorted([cc for r, cc in comp])
    h = r_coords[-1] - r_coords[0] + 1
    w = c_coords[-1] - c_coords[0] + 1

    for rr, cc in comp:
        scaled_r = int((rr - r_coords[0]) * 4 / h) if h > 0 else 0
        scaled_c = int((cc - c_coords[0]) * 4 / w) if w > 0 else 0
        if scaled_r < 4 and scaled_c < 4:
            combined[scaled_r][scaled_c] = 1

print("\nCombined (OR of all scaled components):")
for row in combined:
    print(f" {' '.join(str(x) for x in row)}")

print("\nTarget:")
for row in output:
    print(f" {' '.join(str(x) for x in row)}")

# Perfect match?
match = True
for ii in range(4):
    for jj in range(4):
        if combined[ii][jj] != output[ii][jj]:
            match = False
if match:
    print("MATCHES!")
else:
    print("Does not match")

